import base64,io,json,zipfile,sys,tempfile,time,traceback
from pathlib import Path
import torch,numpy as np
from torch.nn import functional as F
def main():
 root=Path(tempfile.mkdtemp());z=zipfile.ZipFile(io.BytesIO(base64.b64decode('')));z.extractall(root)
 sys.path.insert(0,str(root))
 from model import Classifier
 result=dict(torch=str(torch.__version__),cuda=torch.cuda.is_available(),arms={})
 if not result['cuda']:return dict(result,status='no_cuda')
 result['device']=torch.cuda.get_device_name()
 with np.load(root/'sample.npz') as a:
  v=torch.log1p(torch.tensor(a['x'].astype('float32'))).cuda()
  x=(v-v.mean((0,1)))/v.std((0,1)).clamp_min(.05);y=torch.tensor(a['y'].astype('int64')).cuda()
  result['source_ids']=a['ids'].tolist()
 for arm in ['literal','smooth','lif','attention']:
  torch.manual_seed(137);m=Classifier(arm).cuda();opt=torch.optim.AdamW(m.parameters(),lr=.001)
  first=next(m.parameters());pre=first.detach().clone();times=[];losses=[];gn=[]
  torch.cuda.reset_peak_memory_stats()
  for i in range(4):
   sl=slice(i%2*16,(i%2+1)*16);torch.cuda.synchronize();t=time.perf_counter()
   loss=F.cross_entropy(m(x[sl]),y[sl]);opt.zero_grad(set_to_none=True);loss.backward()
   grad=float(torch.stack([p.grad.square().sum() for p in m.parameters() if p.grad is not None]).sum().sqrt())
   opt.step();torch.cuda.synchronize();times.append(time.perf_counter()-t);losses.append(float(loss.detach()));gn.append(grad)
  change=float((first-pre).abs().max());assert change>0 and np.isfinite(gn).all()
  result['arms'][arm]=dict(warm_s=times[0],step_s=times[1:],loss=losses,gradient_norm=gn,first_tensor_max_update=change,peak_bytes=torch.cuda.max_memory_allocated())
 return dict(result,status='completed_gpu')
try: result=main()
except Exception as e: result={'status':'failed','detail':str(e),'trace':traceback.format_exc()}
Path('result.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result),flush=True)
